\version "2.27.2"
% automatically converted by musicxml2ly from 45h-Repeats-Partial.xml
\pointAndClickOff

\header {
  texidoc = "A repeat starting and ending at a partial bar. The style of the
    back-to-back bar line is 'heavy-heavy' (using the MusicXML encoding as
    exported by Finale)."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    doubleRepeatBarType = ":|.|:"
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c'' {
  \repeat volta 2 {
    \clef "treble" \time 4/4 \key c \major \partial 4 c4 c1 | % 1
    c2. \once \set Score.doubleRepeatBarType = ":..:"
  }
  \repeat volta 2 {
    c4 | % 2
    c1 }
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
